// Demonstrates TARGET TYPING: same lambda, different types based on context
package com.bank.execution.service;

import com.bank.execution.model.TradeResult;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.Callable;
import java.util.function.*;

@Service
@Slf4j
public class TradeExecutionEngine {

    public List<TradeResult> demonstrateTargetTyping() {
        List<TradeResult> results = new ArrayList<>();

        // ═══ CONTEXT 1: Variable declaration ═══
        // The SAME lambda `() -> result` becomes different types based on variable type
        Supplier<TradeResult> syncExecution = () ->
            new TradeResult("EXE-101", "RELIANCE", "FILLED", "Supplier");
        // Compiler sees: target = Supplier<TradeResult> → lambda becomes Supplier

        Callable<TradeResult> asyncExecution = () ->
            new TradeResult("EXE-102", "TCS", "FILLED", "Callable");
        // Compiler sees: target = Callable<TradeResult> → SAME lambda shape becomes Callable!

        results.add(syncExecution.get());
        try { results.add(asyncExecution.call()); }
        catch (Exception e) { /* Callable declares throws Exception */ }

        log.info("[CONTEXT 1] Same lambda shape → Supplier in one variable, Callable in another");

        // ═══ CONTEXT 2: Method parameter ═══
        // Lambda type inferred from the method parameter type
        results.add(executeSync(() ->
            new TradeResult("EXE-103", "HDFC", "FILLED", "via method param → Supplier")));
        // Compiler sees: executeSync(Supplier<TradeResult>) → lambda becomes Supplier

        results.add(executeAsync(() ->
            new TradeResult("EXE-104", "INFY", "FILLED", "via method param → Callable")));
        // Compiler sees: executeAsync(Callable<TradeResult>) → lambda becomes Callable

        log.info("[CONTEXT 2] Same lambda shape → type determined by method parameter");

        // ═══ CONTEXT 3: Return type ═══
        Supplier<TradeResult> fromReturn = createSupplier();
        results.add(fromReturn.get());
        log.info("[CONTEXT 3] Lambda type from return type of method");

        // ═══ CONTEXT 4: Explicit cast ═══
        // When context is ambiguous → cast resolves
        results.add(((Supplier<TradeResult>) () ->
            new TradeResult("EXE-106", "BAJAJ", "FILLED", "via explicit cast")).get());
        log.info("[CONTEXT 4] Cast resolves ambiguity");

        return results;
    }

    // Method that accepts Supplier
    private TradeResult executeSync(Supplier<TradeResult> execution) {
        log.info("  Executing SYNC (Supplier — no throws)");
        return execution.get();
    }

    // Method that accepts Callable
    private TradeResult executeAsync(Callable<TradeResult> execution) {
        log.info("  Executing ASYNC (Callable — throws Exception)");
        try { return execution.call(); }
        catch (Exception e) { throw new RuntimeException(e); }
    }

    // Return type determines lambda type
    private Supplier<TradeResult> createSupplier() {
        return () -> new TradeResult("EXE-105", "WIPRO", "FILLED", "via return type → Supplier");
        // Compiler: return type is Supplier → lambda becomes Supplier
    }
}
