// Demonstrates OVERLOAD AMBIGUITY and the fix
package com.bank.execution.service;

import com.bank.execution.model.TradeResult;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import java.util.concurrent.Callable;
import java.util.function.Supplier;

@Service
@Slf4j
public class OrderProcessor {

    // Two overloaded methods accepting different functional interfaces
    // BOTH match the lambda signature () -> TradeResult

    public TradeResult process(Supplier<TradeResult> execution) {
        log.info("[OVERLOAD] Called Supplier overload (no throws)");
        return execution.get();
    }

    public TradeResult process(Callable<TradeResult> execution) {
        log.info("[OVERLOAD] Called Callable overload (throws Exception)");
        try { return execution.call(); }
        catch (Exception e) { throw new RuntimeException(e); }
    }

    /**
     * Demonstrates the ambiguity problem and fix.
     *
     * process(() -> new TradeResult(...));  // COMPILE ERROR! Ambiguous!
     * Compiler: "reference to process is ambiguous"
     * Both Supplier<TradeResult> and Callable<TradeResult> match () -> TradeResult
     *
     * Supplier.get():  returns T, no throws
     * Callable.call(): returns T, throws Exception
     * Lambda () -> x: matches BOTH (it doesn't throw anything)
     *
     * FIX: explicit cast tells compiler which overload
     */
    public TradeResult demonstrateAmbiguityFix() {
        // This would NOT compile:
        // return process(() -> new TradeResult("AMB", "RELIANCE", "FILLED", "ambiguous"));

        // FIX 1: explicit cast to Supplier
        TradeResult r1 = process((Supplier<TradeResult>) () ->
            new TradeResult("FIX-001", "RELIANCE", "FILLED", "cast to Supplier"));

        // FIX 2: explicit cast to Callable
        TradeResult r2 = process((Callable<TradeResult>) () ->
            new TradeResult("FIX-002", "TCS", "FILLED", "cast to Callable"));

        // FIX 3: assign to typed variable first
        Supplier<TradeResult> typed = () ->
            new TradeResult("FIX-003", "HDFC", "FILLED", "typed variable");
        TradeResult r3 = process(typed);  // unambiguous — typed is Supplier

        log.info("[AMBIGUITY] Fixed with cast or typed variable");
        return r1;
    }
}
```

