package com.bank.execution.controller;

import com.bank.execution.dto.ExecutionResponse;
import com.bank.execution.model.TradeResult;
import com.bank.execution.service.*;
import lombok.RequiredArgsConstructor;
import org.springframework.web.bind.annotation.*;
import java.util.List;

@RestController
@RequestMapping("/api/v1/execution")
@RequiredArgsConstructor
public class ExecutionController {

    private final TradeExecutionEngine engine;
    private final OrderProcessor processor;

    @GetMapping("/target-typing")
    public ExecutionResponse targetTyping() {
        List<TradeResult> results = engine.demonstrateTargetTyping();
        return new ExecutionResponse("Target typing: same lambda, different types",
            results, "Lambda type determined by: variable type, method param, return type, or cast");
    }

    @GetMapping("/ambiguity-fix")
    public ExecutionResponse ambiguityFix() {
        TradeResult result = processor.demonstrateAmbiguityFix();
        return new ExecutionResponse("Overload ambiguity fixed",
            List.of(result), "Fix: explicit cast (Supplier<T>) or typed variable assignment");
    }
}
