// ─── File: src/test/java/com/bank/execution/service/TradeExecutionEngineTest.java ───
package com.bank.execution.service;

import com.bank.execution.model.TradeResult;
import org.junit.jupiter.api.Test;
import java.util.List;
import java.util.concurrent.Callable;
import java.util.function.Supplier;
import static org.assertj.core.api.Assertions.*;

class TradeExecutionEngineTest {

    TradeExecutionEngine engine = new TradeExecutionEngine();
    OrderProcessor processor = new OrderProcessor();

    @Test
    void shouldInferDifferentTypesFromContext() {
        List<TradeResult> results = engine.demonstrateTargetTyping();

        assertThat(results).hasSizeGreaterThanOrEqualTo(5);
        assertThat(results.get(0).executedVia()).isEqualTo("Supplier");
        assertThat(results.get(1).executedVia()).isEqualTo("Callable");
    }

    @Test
    void shouldResolveAmbiguityWithCast() {
        // Same lambda shape — cast determines which overload
        TradeResult asSupplier = processor.process(
            (Supplier<TradeResult>) () -> new TradeResult("T1", "X", "OK", "Supplier"));
        TradeResult asCallable = processor.process(
            (Callable<TradeResult>) () -> new TradeResult("T2", "Y", "OK", "Callable"));

        assertThat(asSupplier.executedVia()).isEqualTo("Supplier");
        assertThat(asCallable.executedVia()).isEqualTo("Callable");
    }

    @Test
    void sameLambdaDifferentTypes() {
        // PROOF: exact same lambda body, different types
        Supplier<String> asSupplier = () -> "RELIANCE";
        Callable<String> asCallable = () -> "RELIANCE";

        assertThat(asSupplier.get()).isEqualTo("RELIANCE");
        assertThat(asCallable).isNotNull(); // different type, same body
    }
}
